import * as NodeChildProcess from "node:child_process";
import * as NodePath from "node:path";
const desktopDir = "fixture";
NodeChildProcess.execFileSync(process.execPath, [NodePath.join(desktopDir, "scripts/build-browser-secret.mjs")], { stdio: "inherit" });
NodeChildProcess.spawnSync("pkill", ["-f", "--", `root=${desktopDir}`], { stdio: "ignore" });
